function switchDesk(view){deskView=view;document.querySelectorAll('[data-desk-pane]').forEach(p=>p.hidden=p.dataset.deskPane!==view);document.querySelectorAll('[data-desk-view]').forEach(b=>{b.classList.toggle('selected',b.dataset.deskView===view);b.setAttribute('aria-pressed',String(b.dataset.deskView===view));});if(view==='bookings')window.calendarLoad?.();const sms=$('#sms-settings');if(sms)$('[data-desk-pane=more]').append(sms);saveDesk();}
