 if(!searchResults)return;const add=(title,fn)=>{const b=text('button',title,'search-result');b.onclick=fn;out.append(b);};
 for(const r of searchResults.rentals.filter(r=>r.returned))add('Выдача №'+r.id+' · '+r.name+' · возвращено',()=>{if(user.role==='admin')openEdit({...r,paid:r.paid||0});else notice(r.name+' · '+r.phone+' · возвращено '+time(r.returned));});
