function renderNearby(){const out=$('#nearby-list');out.replaceChildren();const rows=nearby.filter(r=>r.details.date>=localTime().slice(0,10)).slice(0,8);for(const r of rows){const box=text('div','','booking-compact'),b=text('button',(r.details.date===localTime().slice(0,10)?'':r.details.date.slice(5).split('-').reverse().join('.')+' ')+r.details.time+' · '+r.details.name+' · '+(data.fleet.find(f=>f.id===r.details.equipment)?.label||r.details.equipment));b.onclick=()=>openBooking(r);box.append(b);const issue=text('button','Выдать');issue.onclick=()=>window.issueBooking(r);box.append(issue);out.append(box);}if(!rows.length)out.append(text('p','Ближайших броней нет.','empty'));}
async function refresh(){if(loading)return;loading=true;try{data=await api('dashboard?day='+encodeURIComponent($('#report-day').value));data.clockOffset=data.now-Date.now();user=data.user;const firstView=!restoredContext;restoreDesk();$('#identity').textContent=user.role==='admin'?'Администратор':'Сотрудник';$('#workspace').hidden=false;$('#login-panel').hidden=true;$('#setup-panel').hidden=true;$('#logout').hidden=false;$('#owner-tools').hidden=user.role!=='admin';if(deskView==='more'){window.cmsLoad?.(user);window.smsLoad?.(user);if($('#sms-settings'))$('[data-desk-pane=more]').append($('#sms-settings'));if(firstView)await loadShift();}if(deskView==='bookings')window.calendarLoad?.();const cash=data.totals.find(x=>x.method==='cash')?.amount||0,card=data.totals.find(x=>x.method==='card')?.amount||0;$('#total').textContent=money(cash+card);$('#cash').textContent=money(cash);$('#card').textContent=money(card);const activeUnits=data.active.reduce((n,r)=>n+r.quantity,0),now=Date.now(),overdue=data.active.filter(r=>r.expected_return<now).length,soon=data.active.filter(r=>r.expected_return>=now&&r.expected_return-now<=600000).length;$('#on-water').textContent=activeUnits;$('#active-count').textContent=data.active.length+' выдач';$('#active-total').textContent=activeUnits;$('#active-overdue').textContent=overdue;$('#active-soon').textContent=soon;$('#fleet').replaceChildren(...data.fleet.map(item=>{const e=text('article',item.label,item.available?'':'none');e.append(text('b',`${item.available} / ${item.total}`));return e;}));renderList('#active-list',data.active,true);renderList('#returned-list',data.returned,false);if(deskView==='bookings')await loadInquiries();await loadNearby();renderSearch();$('#updated').textContent='Обновлено '+new Date().toLocaleTimeString('ru-RU',{timeZone:'Europe/Moscow'});}catch(e){notice(e.message);}finally{loading=false;}}
