function openIssue(restore=true){const f=$('#issue-form');f.reset();issueInquiry=null;$('#issue-source').textContent='';requestId=crypto.randomUUID();$('#issue-equipment').replaceChildren(...data.fleet.map(x=>{const o=text('option',`${x.label} — свободно ${x.available}`);o.value=x.id;o.disabled=x.available===0;return o;}));f.elements.departed.value=localTime();f.elements.expectedReturn.value=new Date(Date.now()+10800000+3600000).toISOString().slice(0,16);$('#issue-status').textContent='';try{const d=JSON.parse(sessionStorage.getItem('rental-draft-'+user.id)||'null');if(restore&&d&&Date.now()-d.at<43200000){for(const [k,v] of Object.entries(d.fields))if(f.elements[k])f.elements[k].value=v;requestId=d.requestId;issueInquiry=d.inquiryId;$('#issue-source').textContent='Восстановлен черновик'+(issueInquiry?' брони № '+issueInquiry:'');}}catch{}$('#issue-dialog').showModal();}
